#!/usr/bin/env python3
"""Sealed v2 package -> Transistor. No authority is generated by this module."""
import argparse
import contextlib
import copy
import datetime as dt
import fcntl
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import time
from urllib.parse import urlsplit
from urllib.request import urlopen

CLI = os.environ.get('TRANSISTOR_CLI', 'transistor')
VALIDATOR = Path(__file__).resolve().parents[2] / 'podcast-release-package/scripts/v2/package.py'
FIELDS = {'title', 'summary', 'description', 'author', 'explicit', 'type', 'number', 'season', 'image_url', 'transcript_text'}
OPS = {'upload', 'create_draft', 'readback', 'publish'}


class Blocked(Exception):
    pass


class ProviderFailure(Exception):
    """Mutation outcome may be unknown; only allowlisted diagnostics may escape."""
    def __init__(self, message, diagnostics=None):
        super().__init__(message)
        self.diagnostics = diagnostics or {}


def transcript_match(actual, expected, manifest):
    if not isinstance(actual,str) or not isinstance(expected,str): return None
    if manifest.get('publication_transcript') != {'version':1,'source':'reading_transcript'}:
        return 'exact' if actual.replace('\r\n','\n').replace('\r','\n') == expected.replace('\r\n','\n').replace('\r','\n') else None
    def transport(value):
        return value.removeprefix('\ufeff').replace('\r\n','\n').replace('\r','\n')
    a,e=transport(actual),transport(expected)
    if a == e: return 'exact'
    if a.removesuffix('\n') == e.removesuffix('\n'): return 'terminal_newline'
    # Only blank lines may disappear or multiply. Never strip text-bearing lines.
    lines=lambda value:[line for line in value.split('\n') if line.strip()]
    if lines(a) == lines(e): return 'blank_line_normalization'
    return None


def cli_diagnostics(result):
    allowed_codes = {'validation_error', 'auth_error', 'http_error', 'rate_limit_error',
                     'network_error', 'partial_batch_error', 'confirmation_required'}
    out = {'returncode': result.returncode}
    try:
        error = json.loads(result.stderr).get('error', {})
        if error.get('code') in allowed_codes:
            out['code'] = error['code']
        if type(error.get('status')) is int and 100 <= error['status'] <= 599:
            out['http_status'] = error['status']
        if type(error.get('exit_code')) is int and 0 <= error['exit_code'] <= 8:
            out['exit_code'] = error['exit_code']
    except (ValueError, TypeError, AttributeError):
        pass
    # Free-text message/details and URLs are never carried forward.
    return out


def validation_runtime_files():
    skills = VALIDATOR.resolve().parents[3]
    files = []
    for name in ('podcast-final-edit', 'podcast-mastering', 'podcast-transcription',
                 'podcast-enrichment', 'podcast-transistor-publish', 'podcast-release-package',
                 'podcast-production-workflow'):
        files.extend(p for p in (skills / name).rglob('*') if p.is_file()
                     and p.suffix in ('.py', '.html', '.json', '.css', '.js') and 'tests' not in p.parts)
    for executable in ('ffmpeg', 'ffprobe'):
        resolved = shutil.which(executable)
        if not resolved:
            raise Blocked('Validation runtime executable missing')
        files.append(Path(resolved))
    files.append(Path(sys.executable))
    return sorted(set(files))


def validation_fingerprint(package, manifest):
    """Actual content closure, never mtime or manifest-asserted hashes; process-local only."""
    package = Path(package).resolve()
    paths = {package / 'episode.json', package / 'seal.json'}
    def local(rel):
        path = package / rel
        if Path(rel).is_absolute() or '..' in Path(rel).parts or not path.resolve().is_relative_to(package):
            raise Blocked('Unsafe validation dependency path')
        if any(p.is_symlink() for p in (path, *path.parents) if p.is_relative_to(package) and p != package):
            raise Blocked('Validation dependency symlink')
        return path
    for art in manifest['artifacts'].values():
        paths.add(local(art['path']))
    for source in manifest.get('sources', []):
        path = Path(source['path'])
        paths.add(path if path.is_absolute() else local(source['path']))
    for ref in manifest.get('reviews', []):
        path = local(ref)
        paths.add(path)
        for shot in read(path).get('screenshots', []):
            paths.add(local(shot['path']))
    # Derived evidence is separately traversed even when all its paths are also artifact roles.
    lineage = manifest['artifacts'].get('edit_lineage')
    if lineage:
        for evidence in read(local(lineage['path'])).get('evidence', {}).values():
            paths.add(local(evidence['path']))
    paths.update(validation_runtime_files())
    return digest_bytes(canonical({str(path): digest_file(path) for path in sorted(paths)}))


def digest_bytes(value):
    return hashlib.sha256(value).hexdigest()


def digest_file(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()


def read(path):
    return json.loads(Path(path).read_text())


def persist(path, value):
    path = Path(path)
    tmp = path.with_suffix('.tmp')
    with tmp.open('w') as f:
        json.dump(value, f, ensure_ascii=False, sort_keys=True, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)
    fd = os.open(path.parent, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def safe_url(value):
    if not isinstance(value, str):
        raise Blocked('Missing public media URL')
    u = urlsplit(value)
    if u.scheme != 'https' or not u.hostname or u.username or u.password or u.query or u.fragment:
        raise Blocked('Media URL must be public HTTPS without credentials or query')
    return value


@contextlib.contextmanager
def episode_lock(episode_key):
    # Independent of --state-dir: two controllers cannot evade exclusion with different roots.
    root = Path(tempfile.gettempdir()) / ('podcast-transistor-publish-' + str(os.getuid()))
    root.mkdir(mode=0o700, exist_ok=True)
    if root.is_symlink() or root.stat().st_uid != os.getuid():
        raise Blocked('Unsafe lock directory')
    path = root / (digest_bytes(episode_key.encode()) + '.lock')
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise Blocked('Episode is owned by another controller') from None
        yield
    finally:
        os.close(fd)


def decoded_pcm_identity(path, scratch):
    """Hash every native-rate/native-channel decoded sample; no tolerance or resampling."""
    try:
        probe = subprocess.run(['ffprobe', '-v', 'error', '-select_streams', 'a',
                                '-show_entries', 'stream=sample_rate,channels', '-of', 'json', str(path)],
                               capture_output=True, timeout=30)
        streams = json.loads(probe.stdout)['streams']
        if probe.returncode or len(streams) != 1:
            raise Blocked('Audio identity requires exactly one audio stream')
        rate, channels = int(streams[0]['sample_rate']), int(streams[0]['channels'])
        if rate <= 0 or channels <= 0:
            raise Blocked('Invalid decoded audio geometry')
        pcm_path = Path(scratch) / 'decoded.f32le'
        with pcm_path.open('wb') as output:
            decode = subprocess.run(['ffmpeg', '-nostdin', '-hide_banner', '-v', 'error', '-i', str(path),
                                     '-map', '0:a:0', '-vn', '-sn', '-dn', '-c:a', 'pcm_f32le',
                                     '-f', 'f32le', 'pipe:1'], stdout=output, stderr=subprocess.PIPE, timeout=600)
        if decode.returncode:
            raise Blocked('Exact PCM decoding failed')
        size = pcm_path.stat().st_size
        if not size or size % (4 * channels):
            raise Blocked('Invalid decoded PCM sample count')
        identity = {'sha256': digest_file(pcm_path), 'bytes': size, 'sample_rate': rate,
                    'channels': channels, 'sample_format': 'f32le', 'sample_frames': size // (4 * channels)}
        pcm_path.unlink()
        return identity
    except (subprocess.TimeoutExpired, OSError, KeyError, ValueError):
        raise Blocked('Exact PCM identity verification unavailable') from None


class CLIProvider:
    def __init__(self, http_timeout=300):
        if not isinstance(http_timeout, int) or not 1 <= http_timeout <= 1800:
            raise Blocked('HTTP timeout must be an integer from 1 to 1800 seconds')
        self.http_timeout = http_timeout

    def fetch(self, url):
        safe_url(url)
        try:
            with urlopen(url, timeout=30) as r:
                safe_url(r.url)
                body = r.read(20 * 1024 * 1024 + 1)
                if len(body) > 20 * 1024 * 1024:
                    raise Blocked('Readback asset too large')
                return body, r.headers.get_content_type()
        except OSError:
            raise ProviderFailure('Public asset readback failed') from None

    def fetch_media(self, url, expected_bytes, source_path=None):
        """Allow bounded tag/artwork growth; compare all decoded samples if file bytes differ."""
        safe_url(url)
        h = hashlib.sha256()
        count = 0
        started = time.monotonic()
        try:
            with tempfile.TemporaryDirectory(prefix='podcast-audio-readback-') as scratch:
                remote_path = Path(scratch) / 'remote.audio'
                with urlopen(url, timeout=30) as r, remote_path.open('wb') as output:
                    safe_url(r.url)
                    mime = r.headers.get_content_type()
                    if not mime.startswith('audio/'):
                        raise Blocked('Provider audio MIME mismatch')
                    while True:
                        chunk = r.read(1024 * 1024)
                        if not chunk:
                            break
                        count += len(chunk)
                        if count > expected_bytes + 8 * 1024 * 1024 or time.monotonic() - started > 600:
                            raise Blocked('Provider audio size or bounded download time mismatch')
                        h.update(chunk)
                        output.write(chunk)
                evidence = {'sha256': h.hexdigest(), 'bytes': count, 'mime': mime}
                if source_path and (count != expected_bytes or h.hexdigest() != digest_file(source_path)):
                    source_pcm = decoded_pcm_identity(source_path, scratch)
                    remote_pcm = decoded_pcm_identity(remote_path, scratch)
                    if source_pcm != remote_pcm:
                        raise Blocked('Provider audio identity mismatch: decoded PCM differs')
                    evidence['exact_pcm'] = {'source': source_pcm, 'remote': remote_pcm}
                return evidence
        except OSError:
            raise ProviderFailure('Public audio identity readback failed') from None

    def call(self, args):
        try:
            result = subprocess.run([CLI, '--output', 'json', '--max-retries', '0', '--timeout', str(self.http_timeout), *args],
                                    capture_output=True, timeout=max(600, 2 * self.http_timeout + 60))
            if result.returncode:
                raise ProviderFailure('CLI call failed; sanitized diagnostics available', cli_diagnostics(result))
            return json.loads(result.stdout)
        except subprocess.TimeoutExpired:
            raise ProviderFailure('CLI subprocess timed out; outcome unknown', {'code': 'subprocess_timeout'}) from None
        except (json.JSONDecodeError, OSError):
            raise ProviderFailure('CLI outcome unavailable; raw output suppressed', {'code': 'invalid_or_unavailable_response'}) from None


def validate_release(package):
    try:
        p = subprocess.run([sys.executable, str(VALIDATOR), 'validate', '--package', str(package), '--release', '--require-seal'],
                           capture_output=True, timeout=600)
        report = json.loads(p.stdout)
        if p.returncode or report.get('valid') is not True:
            raise Blocked('Fresh shared release validation failed')
        return report
    except (subprocess.TimeoutExpired, json.JSONDecodeError, OSError):
        raise Blocked('Shared release validator unavailable') from None


class Controller:
    required_operations = OPS
    def __init__(self, package, authorization, state_dir, provider=None, validator=validate_release,
                 poll_count=6, poll_seconds=5, artwork_verification=None, http_timeout=300):
        self.package = Path(package).resolve()
        self.authorization_path = Path(authorization)
        self.state_root = Path(state_dir).resolve()
        self.provider = provider or CLIProvider(http_timeout)
        self._validation_cache = None
        self.validator = validator
        self.poll_count = poll_count
        self.poll_seconds = poll_seconds
        self.artwork_verification = Path(artwork_verification) if artwork_verification else None

    def fresh(self):
        m = read(self.package / 'episode.json')
        a = read(self.authorization_path)
        if m.get('contract_version') != '2.0' or m.get('review_mode') != 'delegated_release':
            raise Blocked('Only sealed v2 delegated_release packages may publish')
        if a.get('contract_version') != '2.0' or a.get('actor') != 'user' or a.get('revoked') is not False:
            raise Blocked('Missing or revoked explicit user authority')
        for key in ('authorization_id', 'source_ref', 'original_user_quote'):
            if not isinstance(a.get(key), str) or not a[key].strip():
                raise Blocked('Incomplete authorization provenance: ' + key)
        if a.get('source_ref_kind') != 'original_user_message':
            raise Blocked('Authority must point to original user message')
        if not self.required_operations.issubset(set(a.get('allowed_operations', []))):
            raise Blocked('Authority does not allow complete publish operation')
        if a.get('expires_at'):
            try:
                expiry = dt.datetime.fromisoformat(a['expires_at'].replace('Z', '+00:00'))
                if expiry.tzinfo is None or expiry <= dt.datetime.now(dt.timezone.utc):
                    raise ValueError()
            except (TypeError, ValueError):
                raise Blocked('Expired or invalid authorization expiry') from None
        for key in ('episode_key', 'show_id', 'package_revision'):
            if a.get(key) != m.get(key) or not m.get(key):
                raise Blocked('Authorization binding mismatch: ' + key)
        self.m, self.a = m, a
        payload_art = m['artifacts']['transistor_payload']
        audio_art = m['artifacts']['delivery_audio']
        def artifact(entry):
            p = (self.package / entry['path']).resolve()
            if not p.is_relative_to(self.package) or not p.is_file() or digest_file(p) != entry['sha256']:
                raise Blocked('Artifact path or hash mismatch')
            return p
        payload_path = artifact(payload_art)
        self.audio = artifact(audio_art)
        self.payload = read(payload_path)
        if set(self.payload) != FIELDS or not self.payload['title'] or any(v is None for v in self.payload.values()):
            raise Blocked('Payload requires exactly the ten supported flat fields')
        safe_url(self.payload['image_url'])
        binding = {'episode_key': m['episode_key'], 'show_id': m['show_id'],
                   'package_revision': m['package_revision'], 'manifest_sha256': digest_file(self.package / 'episode.json'),
                   'release_audio_sha256': digest_file(self.audio), 'payload_sha256': digest_bytes(canonical(self.payload))}
        if any(a.get(k) != v for k, v in binding.items()):
            raise Blocked('Authorization hash binding mismatch')
        fingerprint = validation_fingerprint(self.package, m)
        if self._validation_cache and self._validation_cache[0] == fingerprint:
            report = copy.deepcopy(self._validation_cache[1])
        else:
            self._validation_cache = None
            report = self.validator(self.package)
            if validation_fingerprint(self.package, read(self.package / 'episode.json')) != fingerprint:
                raise Blocked('Validation inputs changed during full verification')
        if report.get('valid') is not True or report.get('audio_sha256') != binding['release_audio_sha256'] or report.get('payload_sha256') != binding['payload_sha256']:
            raise Blocked('Shared release report does not match authorized candidate')
        self._validation_cache = (fingerprint, copy.deepcopy(report))
        if hasattr(self, 'binding') and binding != self.binding:
            raise Blocked('Candidate changed during operation')
        self.binding = binding
        return binding

    def save(self):
        persist(self.state_path, self.state)

    def journal(self, operation, outcome, **evidence):
        # Evidence is caller-whitelisted IDs/hashes/public URLs only. Never persist raw API responses.
        row = {'time': dt.datetime.now(dt.timezone.utc).isoformat(), 'operation': operation, 'outcome': outcome,
               'authorization_id': self.a['authorization_id'], **evidence}
        with (self.work / 'journal.jsonl').open('a') as f:
            f.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + '\n')
            f.flush()
            os.fsync(f.fileno())

    def mutate(self, op, args):
        self.fresh()
        self.provider.call([*args, '--dry-run'])
        self.fresh()
        if digest_file(self.snapshot) != self.binding['release_audio_sha256']:
            raise Blocked('Frozen audio changed')
        self.state['pending'] = op
        self.save()  # Durable intent first, so any interruption fails closed.
        self.journal(op, 'attempted')
        try:
            result = self.provider.call(args)
        except ProviderFailure as error:
            self.journal(op, 'reconcile_required', diagnostics=error.diagnostics)
            raise
        return result

    def get(self, remote_id):
        r = self.provider.call(['episodes', 'get', str(remote_id)])['data']
        if str(r.get('id')) != str(remote_id):
            raise Blocked('Provider returned wrong episode ID')
        return r

    def listing(self):
        data = self.provider.call(['episodes', 'list', '--show-id', self.m['show_id'], '--all-pages'])['data']
        if not isinstance(data, list):
            raise Blocked('Invalid full-page list result')
        return data

    def compare(self, remote):
        attrs = remote.get('attributes', {})
        show = remote.get('relationships', {}).get('show', {}).get('data', {}).get('id')
        if str(show) != self.m['show_id']:
            raise Blocked('Provider show relationship mismatch')
        for key, expected in self.payload.items():
            actual = attrs.get(key)
            if key == 'image_url' and actual != expected:
                self.verify_artwork(remote, actual)
                continue
            if key == 'transcript_text' and actual is None:
                transcripts = attrs.get('transcripts', [])
                txt = [t['url'] for t in transcripts if t.get('format') == 'txt' and t.get('url')]
                if len(txt) != 1:
                    raise Blocked('Provider transcript txt endpoint missing or ambiguous')
                data, mime = self.provider.fetch(safe_url(txt[0]))
                if mime not in ('text/plain', 'text/plain; charset=utf-8'):
                    raise Blocked('Provider transcript MIME mismatch')
                actual = data.decode('utf-8-sig')
                actual = actual.replace('\r\n', '\n').replace('\r', '\n')
                expected = expected.replace('\r\n', '\n').replace('\r', '\n')
            # Only documented CLI scalar representations: integer strings and bool strings.
            if key in ('number', 'season') and actual is not None and expected is not None:
                actual, expected = str(actual), str(expected)
            if key == 'explicit' and isinstance(actual, str) and actual in ('true', 'false'):
                actual = actual == 'true'
            if key == 'transcript_text':
                self.compare_transcript(actual, expected)
                continue
            if actual != expected:
                raise Blocked('Provider payload mismatch: ' + key)
        return attrs

    def compare_transcript(self, actual, expected):
        method=transcript_match(actual,expected,self.m)
        if not method: raise Blocked('Provider payload mismatch: transcript_text')
        self.transcript_evidence={'variant':self.m.get('publication_transcript',{'source':'aligned_transcript'}),'comparison':method,'expected_sha256':digest_bytes(expected.encode()),'actual_sha256':digest_bytes(actual.encode())}
        self.journal('transcript_readback','verified',**self.transcript_evidence)

    def verify_artwork(self, remote, remote_url):
        if not self.artwork_verification:
            raise Blocked('Provider payload mismatch: image_url; independent artwork verification required')
        proof = read(self.artwork_verification)
        expected = {'contract_version': '2.0', 'episode_key': self.m['episode_key'],
                    'show_id': self.m['show_id'], 'package_revision': self.m['package_revision'],
                    'remote_id': str(remote['id']), 'source_image_url': self.payload['image_url'],
                    'remote_image_url': remote_url, 'verification_method': 'independent_visual_review', 'verified': True}
        if any(proof.get(k) != v for k, v in expected.items()) or not proof.get('reviewer_id') or not proof.get('source_ref'):
            raise Blocked('Artwork proof does not bind this remote candidate')
        source_sha = proof.get('source_image_sha256')
        art = self.m['artifacts'].get('artwork')
        images = [art] if art and art['sha256'] == source_sha else []
        if not images or any(digest_file(self.package / a['path']) != source_sha for a in images):
            raise Blocked('Artwork proof source hash missing from sealed artifacts')
        data, mime = self.provider.fetch(safe_url(remote_url))
        if not mime.startswith('image/') or digest_bytes(data) != proof.get('remote_image_sha256'):
            raise Blocked('Artwork proof remote content changed')
        self.journal('artwork_readback', 'verified', remote_id=str(remote['id']),
                     source_image_sha256=source_sha, remote_image_sha256=digest_bytes(data),
                     proof_sha256=digest_file(self.artwork_verification))

    def verify_audio(self, remote):
        attrs = remote['attributes']
        media_url = safe_url(attrs.get('media_url') or attrs.get('audio_url'))
        evidence = self.provider.fetch_media(media_url, self.audio.stat().st_size, self.audio)
        exact_bytes = evidence.get('sha256') == self.binding['release_audio_sha256'] and evidence.get('bytes') == self.audio.stat().st_size
        pcm = evidence.get('exact_pcm', {})
        if not exact_bytes and (not pcm.get('source') or pcm.get('source') != pcm.get('remote')):
            raise Blocked('Provider audio identity mismatch; remote bytes or exact PCM must match authorized delivery')
        if not evidence.get('mime', '').startswith('audio/'):
            raise Blocked('Provider audio MIME mismatch')
        self.audio_evidence = {'remote_id': str(remote['id']), 'media_url': media_url,
                               'remote_audio_sha256': evidence['sha256'], 'remote_audio_bytes': evidence['bytes'],
                               'mime': evidence['mime'], 'verification_method': 'exact_delivery_bytes_sha256' if exact_bytes else 'exact_decoded_pcm_sha256',
                               'exact_pcm': pcm if not exact_bytes else None}
        self.journal('audio_readback', 'verified', **self.audio_evidence)

    def ready(self, remote_id):
        for attempt in range(self.poll_count):
            r = self.get(remote_id)
            attrs = r.get('attributes', {})
            if attrs.get('processing_failed') or attrs.get('processing_failure'):
                raise Blocked('Provider media processing failed')
            if attrs.get('audio_processing') is False:
                safe_url(attrs.get('media_url') or attrs.get('audio_url'))
                self.verify_audio(r)
                self.compare(r)
                self.journal('readback', 'verified', remote_id=str(remote_id),
                             response_sha256=digest_bytes(canonical(r)), status=attrs.get('status'),
                             payload_sha256=self.binding['payload_sha256'])
                return r
            if attempt + 1 < self.poll_count:
                time.sleep(self.poll_seconds)
        raise Blocked('Provider media processing is pending or unknown')

    def reconcile(self):
        pending = self.state.get('pending')
        if pending == 'upload':
            raise Blocked('reconcile_required: upload outcome unknown; never re-upload blindly')
        if pending == 'create_draft' and not self.state.get('remote_id'):
            found = []
            for item in self.listing():
                # Exact upload URL supplies causal evidence; title alone cannot claim a remote episode.
                if item.get('attributes', {}).get('audio_url') == self.state.get('audio_url'):
                    r = self.get(item['id'])
                    self.compare(r)
                    found.append(r)
            if len(found) != 1:
                raise Blocked('reconcile_required: create outcome cannot be uniquely identified')
            self.state['remote_id'] = str(found[0]['id'])
            self.state['pending'] = None
            self.save()
            self.journal('create_draft', 'reconciled', remote_id=self.state['remote_id'])
        if pending == 'publish':
            r = self.ready(self.state['remote_id'])
            if r['attributes'].get('status') != 'published':
                raise Blocked('reconcile_required: publish outcome unconfirmed; no retry')
            self.state.update(pending=None, status='published_verified')
            self.save()
            self.journal('publish', 'reconciled', remote_id=self.state['remote_id'])

    def run(self, mode):
        self.fresh()  # No provider read or mutation before authorization checks.
        with episode_lock(self.m['episode_key']):
            self.fresh()
            if mode == 'plan':
                return {'status': 'plan', **self.binding, 'allowed_operations': sorted(OPS)}
            self.work = self.state_root / digest_bytes(self.m['episode_key'].encode())
            self.work.mkdir(parents=True, exist_ok=True)
            self.state_path = self.work / 'state.json'
            self.snapshot = self.work / 'upload-input.mp3'
            self.state = read(self.state_path) if self.state_path.exists() else {'binding': self.binding, 'pending': None}
            if self.state.get('binding') != self.binding:
                raise Blocked('Existing episode state binds another candidate; explicit reconciliation required')
            if self.a.get('remote_id'):
                rid = str(self.a['remote_id'])
                if self.state.get('remote_id') not in (None, rid):
                    raise Blocked('Remote ID binding mismatch')
                self.state['remote_id'] = rid
                self.save()
            if not self.snapshot.exists():
                shutil.copyfile(self.audio, self.snapshot)
            if digest_file(self.snapshot) != self.binding['release_audio_sha256']:
                raise Blocked('Snapshot hash mismatch')
            self.reconcile()
            remote_id = self.state.get('remote_id')
            if remote_id:
                remote = self.ready(remote_id)  # Resume reads same stable ID before duplicate probe.
            else:
                remote = None
            for item in self.listing():
                if str(item.get('id')) != remote_id and item.get('attributes', {}).get('title') == self.payload['title']:
                    raise Blocked('Possible duplicate title requires identity reconciliation')
            if remote and remote['attributes'].get('status') == 'published':
                self.state.update(status='published_verified', pending=None)
                self.save()
                return self.receipt('already_published_noop', remote)
            if remote and remote['attributes'].get('status') != 'draft':
                raise Blocked('Existing episode is not draft; explicit reconciliation required')
            if not remote_id:
                if not self.state.get('audio_url'):
                    upload = self.mutate('upload', ['episodes', 'upload', str(self.snapshot), '--content-type', 'audio/mpeg'])
                    self.state.update(audio_url=safe_url(upload.get('audio_url')), pending=None)
                    self.save()
                    self.journal('upload', 'verified', audio_url=self.state['audio_url'], audio_sha256=self.binding['release_audio_sha256'])
                args = ['episodes', 'create', '--show-id', self.m['show_id']]
                for key, value in {**self.payload, 'audio_url': self.state['audio_url']}.items():
                    if value is None:
                        raise Blocked('Create cannot represent null payload values')
                    args += ['--set', key + '=' + (str(value).lower() if isinstance(value, bool) else str(value))]
                try:
                    created = self.mutate('create_draft', args)
                    remote_id = str(created['data']['id'])
                    if not remote_id.isdigit():
                        raise ProviderFailure('Create response has invalid ID')
                    self.state.update(remote_id=remote_id, pending=None)
                    self.save()
                    self.journal('create_draft', 'response_received', remote_id=remote_id)
                except ProviderFailure:
                    self.reconcile()
                    remote_id = self.state['remote_id']
            remote = self.ready(remote_id)
            if remote['attributes'].get('status') != 'draft':
                raise Blocked('Draft status not verified')
            try:
                self.mutate('publish', ['episodes', 'publish', remote_id, '--status', 'published', '--yes'])
            except ProviderFailure:
                self.reconcile()
            remote = self.ready(remote_id)
            if remote['attributes'].get('status') != 'published':
                raise Blocked('reconcile_required: published status not observed')
            self.state.update(status='published_verified', pending=None)
            self.save()
            self.journal('publish', 'verified', remote_id=remote_id)
            return self.receipt('published_verified', remote)

    def receipt(self, status, remote):
        result = {'status': status, 'remote_id': str(remote['id']), **self.binding,
                  'provider_status': remote['attributes']['status'], 'remote_bytes_sha256_verified': self.audio_evidence['verification_method'] == 'exact_delivery_bytes_sha256',
                  'audio_verification': self.audio_evidence,
                  'transcript_verification': getattr(self,'transcript_evidence',None)}
        url = remote['attributes'].get('share_url')
        if url:
            result['share_url'] = safe_url(url)
        persist(self.work / 'receipt.json', result)
        return result


def main():
    p = argparse.ArgumentParser(description=__doc__)
    for name in ('package', 'authorization', 'state-dir'):
        p.add_argument('--' + name, required=True, type=Path)
    p.add_argument('--mode', choices=('plan', 'publish'), required=True)
    p.add_argument('--artwork-verification', type=Path)
    p.add_argument('--http-timeout', type=int, default=300)
    args = p.parse_args()
    controller = None
    try:
        controller = Controller(args.package, args.authorization, args.state_dir, artwork_verification=args.artwork_verification, http_timeout=args.http_timeout)
        result = controller.run(args.mode)
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return 0
    except (Blocked, ProviderFailure) as e:
        print(json.dumps({'status': 'blocked', 'reason': str(e),
                          'remote_id': getattr(controller, 'state', {}).get('remote_id'),
                          'pending': getattr(controller, 'state', {}).get('pending'),
                          'diagnostics': getattr(e, 'diagnostics', {})}, ensure_ascii=False))
        return 2
    except (KeyError, TypeError, ValueError, OSError):
        print(json.dumps({'status': 'blocked', 'reason': 'Invalid package, authorization, state or provider response'}))
        return 2


if __name__ == '__main__':
    sys.exit(main())
